/// ABI v1 section 3, rendered from plan.lifecycle: `ak_init` with `AK_INIT_NO_CRYPTO |
/// AK_INIT_NO_PANIC_HOOK`; AK_OK and AK_ALREADY_INITIALIZED are success, anything else
/// is loud. `Ensure` is for code that calls the core through its own imports and must
/// initialise it the same way.
public static unsafe class AbiInit
{
    public const uint Flags = Abi.AK_INIT_NO_CRYPTO | Abi.AK_INIT_NO_PANIC_HOOK;
    public static int Code { get; private set; } = int.MinValue;
    public static void Ensure() => RuntimeHelpers.RunClassConstructor(typeof(Abi).TypeHandle);
    internal static void Run()
    {
        // A GATE CONTROL, not a feature: set, the call is skipped, and against a core
        // built with `init-guard` the first codec call must fail (the planted control).
        if (Environment.GetEnvironmentVariable("AK_GATE_PLANT_NO_INIT") == "1") { Code = -999; return; }
        var o = new ak_init_opts { abi_version = Abi.AK_ABI_VERSION, flags = Flags };
        var e = new ak_err();
        int rc = Abi.ak_init(&o, &e);
        Code = rc;
        if (rc != Abi.AK_OK && rc != Abi.AK_ALREADY_INITIALIZED)
            throw new InvalidOperationException($"ak_init failed: {rc} (code {e.code}, detail {e.detail})");
    }
}

/// The C# side of the layout agreement. `Table` is the C# declaration with the C#
/// compiler's own offsets and sizes (the probe comparison lives in the harness, by
/// name, both ways); `Facts` compares the same compiler's numbers with the loaded
/// core's `ak_layout_facts` (ABI v1 section 10).
public static unsafe class AbiLayout
{
    public sealed class S { public string Name; public int Size; public int Fields; public List<(string Name, int Off, int Size)> F = new List<(string, int, int)>(); }

    private static int Fsz<T>(T* _) where T : unmanaged => sizeof(T);

    /// Every struct this binding declares, with every member: name, offset, size.
    public static List<S> Table()
    {
        var all = new List<S>();
        {
            var s = new S { Name = "ak_str", Size = sizeof(ak_str), Fields = typeof(ak_str).GetFields(System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.Public | System.Reflection.BindingFlags.NonPublic).Length };
